/* Read-only examples, generated by the repository core. No browser-side copy of the rules. */
(()=>{
const root=document.getElementById('trafficExamplesPanel'),data=window.YOHAKU_REPLAY.criteria,COPY=window.CRITERIA_COPY;
let lang=document.documentElement.lang==='en'?'en':'ja',index=0,cap=Number(document.getElementById('cap').value);
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>new Intl.NumberFormat(lang==='ja'?'ja-JP':'en-US').format(n);
const fill=s=>s.replace(/\{threshold\}/g,number(data.threshold)).replace(/\{cap\}/g,String(cap));
root.innerHTML=`
 <div class="criteria-heading"><span class="eyebrow" data-criteria="eyebrow"></span><h3 id="criteriaTitle" data-criteria="title"></h3><p data-criteria="intro"></p></div>
 <div class="criteria-select"><label for="criteriaCase" data-criteria="select"></label><select id="criteriaCase"></select><button id="criteriaPrevious" type="button" data-criteria="previous"></button><button id="criteriaNext" type="button" data-criteria="next"></button></div>
 <div class="criteria-columns">
  <article class="criteria-card"><h4 data-criteria="request"></h4><dl id="criteriaFacts"></dl><p class="criteria-change" data-criteria="different"></p></article>
  <article class="criteria-card criteria-policy"><h4 data-criteria="policy"></h4><ul id="criteriaPolicy"></ul><p id="criteriaCap"></p></article>
 </div>
 <div class="criteria-result" id="criteriaResult" aria-live="polite" aria-atomic="true"><div><small id="criteriaDecisionLabel"></small><h4 id="criteriaOutcome"></h4><span id="criteriaRule"></span></div><div><p id="criteriaReason"></p><p id="criteriaNextStep"></p></div></div>
 <div class="criteria-model" id="criteriaModel"></div>
 <details class="criteria-trace"><summary data-criteria="trace"></summary><p data-criteria="traceNote"></p><ol id="criteriaRules" start="0"></ol></details>
 <details class="criteria-raw"><summary data-criteria="raw"></summary><pre id="criteriaRaw"></pre></details><p class="criteria-note" data-criteria="note"></p>`;
function show(){
 const t=COPY[lang],example=data.examples[index],input=example.input,initial=example.initial,d=example.decision;
 const baseline=data.examples[0].input;
 const grant=input.category==='allowed'?input.grant:'none';
 const facts={category:t.category[input.category],amount:`${number(input.amount)} JPYC`,party:t.party[input.party],risk:t.risk[input.risk],grant:t.grant[grant],...(example.modelChoice?{model:example.modelChoice}:{})};
 $('criteriaFacts').innerHTML=Object.entries(facts).map(([key,value])=>{const changed=key==='model'||(key==='grant'?grant!==baseline.grant:input[key]!==baseline[key]);return `<div${changed?' class="changed"':''}><dt>${t.fields[key]}</dt><dd>${esc(value)}</dd></div>`;}).join('');
 $('criteriaCap').textContent=fill(t.cap);
 $('criteriaOutcome').textContent=t.outcome[d.verdict];$('criteriaDecisionLabel').textContent=t.decided;
 $('criteriaRule').textContent=`${t.rule} · ${initial.rule}`;
 $('criteriaReason').textContent=t.cases[example.id][1];$('criteriaNextStep').textContent=fill(t.nextStep[d.verdict]);
 $('criteriaResult').dataset.verdict=d.verdict;
 $('criteriaModel').textContent=example.modelChoice?`${t.modelUsed}: ${example.modelChoice==='ask'?t.modelAsk:t.modelDrop}`:t.modelSkipped;
 $('criteriaRules').innerHTML=t.rules.map((rule,i)=>`<li class="${i===initial.rule?'matched':i>initial.rule?'skipped':'missed'}"><code>${i}</code><span>${esc(fill(rule))}</span><b>${i===initial.rule?(i===9?t.matchedAI:t.matched):i>initial.rule?t.skipped:t.missed}</b></li>`).join('');
 $('criteriaRaw').textContent=JSON.stringify({simulation:true,executable:false,source:window.YOHAKU_REPLAY.generatedFrom,request:example.request,policyThreshold:data.threshold,screening:input.risk,grant,initial,modelChoice:example.modelChoice,decision:d},null,2);
 $('criteriaPrevious').disabled=index===0;$('criteriaNext').disabled=index===data.examples.length-1;$('criteriaCase').value=example.id;
}
function render(){
 const t=COPY[lang];root.querySelectorAll('[data-criteria]').forEach(e=>e.textContent=t[e.dataset.criteria]);
 $('criteriaCase').innerHTML=data.examples.map((e,i)=>`<option value="${e.id}">${String(i+1).padStart(2,'0')} / ${esc(t.cases[e.id][0])}</option>`).join('');
 $('criteriaPolicy').innerHTML=t.policyLines.map(line=>`<li>${esc(fill(line))}</li>`).join('');
 show();
}
$('criteriaCase').onchange=e=>{index=data.examples.findIndex(x=>x.id===e.target.value);show();};
$('criteriaPrevious').onclick=()=>{index=Math.max(0,index-1);show();};
$('criteriaNext').onclick=()=>{index=Math.min(data.examples.length-1,index+1);show();};
document.addEventListener('launch-language',e=>{lang=e.detail;render();});
document.addEventListener('launch-cap',e=>{cap=e.detail;show();});
render();
})();
